/* fm1-8p's display font (firmware/dfont.c, #55): glyph lookup, widths, drawing, unknown characters.
 * The font data is docs/ui/mockups/display_font.h, generated by render.py. */
#include "../firmware/dfont.h"

/* every character of DFONT_CHARS finds its own glyph; lower case folds to upper */
TT_TEST(dfont_finds_every_glyph)
{
    uint32_t i;
    for (i = 0; i < dfont_n; i++)
        TT_CHECK_EQ(dfont_glyph(dfont_chars[i]), (int32_t)i);
    TT_CHECK_EQ(dfont_glyph('e'), dfont_glyph('E'));
    TT_CHECK_EQ(dfont_glyph('z'), dfont_glyph('Z'));
}

static void run_dfont_tests(void)
{
    TT_RUN(dfont_finds_every_glyph);
}
